 if(phase==2){if(callbackEnd<queued)return;if(EditorApplication.timeSinceStartup-callbackEnd>8){EditorApplication.update-=Tick;Finish("NO VISIBLE CHANGE\n"+diagnostics+"nodes="+doc.nodes.Count+" status="+typeof(StudioModelEditor).GetField("statusText",F).GetValue(editor));return;}int different=pixels.Zip(before,(a,b)=>a.Equals(b)?0:1).Sum();if(different<1000){view.Repaint();return;}diagnostics+="first_changed_frame_ms="+((EditorApplication.timeSinceStartup-queued)*1000).ToString("F2")+" after_callback_ms="+((EditorApplication.timeSinceStartup-callbackEnd)*1000).ToString("F2")+" pixels="+different+"\n";if(++scenario<3){int last=doc.nodes.Count-1;editor.Transforms[last].position=Vector3.left*(3+scenario);doc.ReadTransform(last,editor.Transforms[last]);view.Repaint();phase=1;ready=EditorApplication.timeSinceStartup+.3;return;}EditorApplication.update-=Tick;Finish("PASS timings\n"+diagnostics);return;}
 }catch(Exception ex){EditorApplication.update-=Tick;Finish(diagnostics+ex);}}
